import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"La retta dei numeri reali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnh.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnh.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fn/fnh.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="la-retta-dei-numeri-reali" tabindex="-1">La retta dei numeri reali <a class="header-anchor" href="#la-retta-dei-numeri-reali" aria-label="Permalink to “La retta dei numeri reali”">​</a></h1><p>Facciamo ora la conoscenza di un ente che ci accompagnerà lungo tutta l&#39;analisi matematica e la geometria cartesiana: la retta reale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>R</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{R}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;color:red;">R</span></span></span></span></p><p>In questa retta ad ogni punto corrisponde un numero reale e ad ogni numero reale corrisponde un punto. Cioè esiste una corrispondenza biunivoca fra i punti della retta ed i numeri reali.</p><blockquote><p>C&#39;è da dire che i numeri reali non razionali saranno molti di più dei numeri reali razionali: addirittura avremo che mentre i numeri razionali, per quanto infiniti sono un&#39;infinità numerabile, i numeri reali sono un&#39;infinità non numerabile e, siccome rappresentandoli su una retta, fra un numero e l&#39;altro non esiste più spazio, si parlerà di <strong>continuo</strong></p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};